"""Small helpers: date parsing and money rounding."""

import datetime
from typing import Union

from dateutil import parser as _dateutil_parser
from dateutil.parser import ParserError as _ParserError

Dateish = Union[str, datetime.date]


def parse_date(text):
    """Parse a date string in a wide variety of formats.

    Bare YYYY-MM is treated as the first day of that month. Raises ValueError
    for strings that cannot be interpreted as a date.
    """
    text = text.strip()
    # Handle YYYY-MM explicitly so a bare month always lands on day 1.
    # dateutil would otherwise fill the missing day from today's date.
    try:
        return datetime.datetime.strptime(text, "%Y-%m").date()
    except ValueError:
        pass
    try:
        return _dateutil_parser.parse(text).date()
    except (_ParserError, ValueError, OverflowError) as exc:
        raise ValueError("unrecognized date {!r}".format(text)) from exc

